#include <iostream>

int main() {
    int integer1 = 0;
    int integer2 = 0;

    if (std::cin >> integer1 >> integer2) {
        // Destructive write into sum; nondestructive read of integer1 and integer2
        int sum = integer1 + integer2;

        std::cout << "integer1: " << integer1 << "\n";
        std::cout << "integer2: " << integer2 << "\n";
        std::cout << "Sum is " << sum << "\n";
        std::cout << "Direct sum: " << (integer1 + integer2) << "\n";
    }
    return 0;
}

#include <iostream>

int main() {
    int a = 0;
    int b = 0;

    if (std::cin >> a >> b) {
        if (b == 0) {
            std::cout << "Cannot divide by zero\n";
            return 0;
        }

        int quotient = a / b;
        int remainder = a % b;
        // Straight-line expression evaluating precedence: innermost () first, then *, / from left to right
        int complexResult = (a + b) * (a % b) / 2;

        std::cout << "Quotient: " << quotient << "\n";
        std::cout << "Remainder: " << remainder << "\n";
        std::cout << "Result: " << complexResult << "\n";
    }
    return 0;
}
